  proposal
      .withObject("/operation")
      .put(
          "destinationInputId",
          sessions
              .runnerContext(controller, id, 1)
              .path("authoredInputs")
              .path("inputs")
              .get(0)
              .path("inputId")
              .asText());
  return proposal;
}

